import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.List;

public class ProxyLoggerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static class Polite implements Greeter {
        @Override
        public String greet(String name) {
            return "Hello, " + name;
        }

        @Override
        public String farewell(String name) {
            return "Bye, " + name;
        }
    }

    public static void main(String[] args) {
        List<String> log = new ArrayList<>();
        Greeter real = new Polite();
        Greeter wrapped = null;
        try {
            wrapped = ProxyLogger.logging(real, log);
        } catch (Throwable t) {
            System.out.println("FAIL  logging() threw " + t.getClass().getSimpleName());
            failures++;
        }

        check("logging() returns a Greeter", true, wrapped != null);
        check("the result is a dynamic proxy", true,
                wrapped != null && Proxy.isProxyClass(wrapped.getClass()));
        check("the proxy is not the target itself", true, wrapped != real);
        check("nothing is logged before any call", 0, log.size());

        try {
            check("greet is delegated", "Hello, Ada", wrapped == null ? null : wrapped.greet("Ada"));
            check("greet was logged", "[greet]", log.toString());

            check("farewell is delegated", "Bye, Bo", wrapped == null ? null : wrapped.farewell("Bo"));
            check("both calls logged in order", "[greet, farewell]", log.toString());
        } catch (Throwable t) {
            System.out.println("FAIL  calling the proxy threw " + t.getClass().getSimpleName());
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

